def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    desperate_count = 0
    rich_aggressive = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 0.85 * opp.get('daily_salary', DAILY_SALARY) and opp.get('budget', 0) > 100:
                    rich_aggressive += 1

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    slots = max(1, int(supply // WATER_REQ))
    low_supply = slots <= 1
    high_supply = slots >= 2

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    emergency = hp <= 2 or no_water_days >= 1
    severe_emergency = hp <= 1 or no_water_days >= 2

    if severe_emergency:
        bid = min(budget, max(DAILY_SALARY * 1.15, highest_prev + 6.0, 82.0))
        return float(max(0.0, bid))

    if emergency:
        if low_supply:
            bid = min(budget, max(DAILY_SALARY * 0.95, highest_prev + 3.0, 68.0))
        else:
            bid = min(budget, max(DAILY_SALARY * 0.72, avg_prev + 1.5, 52.0))
        return float(max(0.0, bid))

    if low_supply:
        if rich_aggressive >= 2 and hp >= 4:
            bid = min(budget, DAILY_SALARY * 0.22)
        elif highest_prev >= 120:
            bid = min(budget, DAILY_SALARY * 0.28)
        elif highest_prev >= 80:
            bid = min(budget, max(DAILY_SALARY * 0.40, highest_prev - 18.0))
        else:
            bid = min(budget, max(DAILY_SALARY * 0.58, highest_prev + 2.0, 41.0))
    else:
        if highest_prev >= 120:
            bid = min(budget, DAILY_SALARY * 0.18)
        elif avg_prev >= 80:
            bid = min(budget, DAILY_SALARY * 0.30)
        else:
            bid = min(budget, max(DAILY_SALARY * 0.34, avg_prev * 0.55 + 6.0, 24.0))

    if desperate_count >= 2 and low_supply:
        bid = max(0.0, bid + 8.0)

    if day >= 8 and hp >= 4 and budget < DAILY_SALARY * 3:
        bid = min(bid, DAILY_SALARY * 0.30)

    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Identify alive opponents
    alive_opps = [o for o in opponents_status.values() if o.get('alive')]
    if not alive_opps:
        return float(min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    # Use only yesterday previous_trace for immediate reaction
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Base aggressiveness from yesterday bidding pressure
    base = DAILY_SALARY * 0.6  # mid
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        avg_prev_bid = sum(prev_bids) / float(len(prev_bids))
        # If others were near max, we slightly overbid; if not, stay near avg
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            base = max(base, avg_prev_bid * 0.95)
        else:
            base = max(base, avg_prev_bid * 0.8)

    # Adjust for current supply: lower supply => higher bid to avoid no-water days
    # Normalize supply into [0,1] where 0 is MIN_SUPPLY (tight) and 1 is MAX_SUPPLY (plenty)
    if MAX_SUPPLY > MIN_SUPPLY:
        t = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    else:
        t = 0.5
    t = max(0.0, min(1.0, t))

    # Tight supply: push bid up; plentiful: pull down
    supply_multiplier = 1.15 - 0.3 * t  # between ~0.85 and ~1.15

    # Health/budget risk control
    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = float(my_status.get('no_water_days', 0.0))

    # If I'm close to danger or accumulating no-water days, bid more
    danger_factor = 1.0
    if hp <= 2.5:
        danger_factor = 1.6
    elif hp <= 4.0:
        danger_factor = 1.3
    if no_water_days >= 2:
        danger_factor *= 1.25

    target = base * supply_multiplier * danger_factor

    # Keep within budget and avoid overspending: cap at 1.2*DAILY_SALARY unless budget forces
    cap = DAILY_SALARY * 1.2
    bid = min(budget, cap, target)

    # If budget is very small, still bid something meaningful when supply is tight
    if bid <= 0 and budget > 0:
        bid = min(budget, DAILY_SALARY * (0.3 if t > 0.5 else 0.7))

    return float(max(0.0, bid))

